        "text": "JDK",
        "refs": ["Q0006"]
      },
      "definition_text": {
        "text": "JDK stands for Java Development Kit, a software development environment for building Java applications.",
        "refs": ["Q0006"]
      },
      "context": null
    },
    {
      "term": {
        "text": "Java Runtime Environment",
        "refs": ["Q0007"]
      },
      "definition_text": {
        "text": "Java Runtime Environment (JRE) is part of the JDK that allows Java programs to run.",
        "refs": ["Q0007"]
      },
      "context": null
    }
  ],
  "examples": [],
  "explanations": [],
  "facts": [
    {
      "fact_text": {
        "text": "The JDK includes a compiler, reusable code libraries, a Java Runtime Environment, and other tools.",
        "refs": ["Q0007"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The JDK can be downloaded for various platforms such as Linux, macOS, and Windows.",
        "refs": ["Q0007"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "On macOS, the JDK is provided as a .dmg file.",
        "refs": ["Q0008"]
      },
      "fact_type": null
    }
  ],
